368	// inspired by pkg/ipam/crd.go (as AWS, Azure reserves the first subnet IP for the gw).
369	// Ref: https://docs.microsoft.com/en-us/azure/virtual-network/virtual-networks-faq#are-there-any-restrictions-on-using-ip-addresses-within-these-subnets
370	func deriveGatewayIP(subnetIP netip.Addr) string {
371		return subnetIP.Next().String()
372	}
