375	// interfaces as instanceMap
376	func (c *Client) GetInstances(ctx context.Context, subnets ipamTypes.SubnetMap) (*ipamTypes.InstanceMap, error) {
377		networkInterfaces, err := c.ListAllNetworkInterfaces(ctx)
378		if err != nil {
379			return nil, err
380		}
381	
382		return c.ParseInterfacesIntoInstanceMap(networkInterfaces, subnets), nil
383	}
