385	// ListAllNetworkInterfaces returns all network interfaces in the resource group
386	// This is exposed to allow callers to fetch network interfaces once and parse them multiple times
387	func (c *Client) ListAllNetworkInterfaces(ctx context.Context) ([]*armnetwork.Interface, error) {
388		networkInterfaces, err := c.listVirtualMachineScaleSetsNetworkInterfaces(ctx)
389		if err != nil {
390			return nil, err
391		}
392	
393		vmInterfaces, err := c.vmNetworkInterfaces(ctx)
394		if err != nil {
395			return nil, err
396		}
397	
398		return append(networkInterfaces, vmInterfaces...), nil
399	}
